<?php use App\Services\CheckoutService as C; $badge = ['pending' => 'warning', 'approved' => 'success', 'rejected' => 'secondary']; ?>
<div class="d-flex flex-wrap gap-2 mb-3"><?php foreach (['' => 'الكل'] + C::CLAIM_STATUSES as $k => $l): ?><a class="badge text-bg-<?= $status === (string)$k ? 'primary' : 'secondary' ?> text-decoration-none fs-6" href="<?= url('school/fees/claims?status=' . $k) ?>"><?= e($l) ?></a><?php endforeach; ?><?php if (can('fees.gateway')): ?><a class="btn btn-sm btn-outline-secondary ms-auto" href="<?= url('school/fees/methods') ?>">إدارة طرق الدفع</a><?php endif; ?></div>
<?php if (!$rows): ?><div class="card-s empty-state"><i class="bi bi-inbox"></i>لا توجد إشعارات.</div><?php endif; ?>
<?php foreach ($rows as $c): ?><div class="card-s mb-3"><div class="d-flex flex-wrap gap-3">
 <div class="flex-grow-1"><div class="d-flex flex-wrap gap-2 align-items-center"><strong><?= e($c['full_name']) ?></strong><small class="text-muted"><?= e($c['student_no']) ?></small><span class="badge text-bg-<?= $badge[$c['status']] ?>"><?= e(C::CLAIM_STATUSES[$c['status']]) ?></span></div>
  <dl class="row small mb-0 mt-1"><dt class="col-sm-3">المبلغ</dt><dd class="col-sm-9"><strong dir="ltr"><?= e(number_format((float)$c['amount'], 2)) ?> <?= e($c['currency']) ?></strong></dd><dt class="col-sm-3">الطريقة</dt><dd class="col-sm-9"><?= e($c['method_label']) ?></dd><dt class="col-sm-3">رقم العملية</dt><dd class="col-sm-9" dir="ltr"><?= e($c['reference_no']) ?></dd><dt class="col-sm-3">تاريخ التحويل</dt><dd class="col-sm-9" dir="ltr"><?= e($c['paid_on']) ?></dd><dt class="col-sm-3">ولي الأمر</dt><dd class="col-sm-9"><?= e($c['guardian'] ?? '—') ?></dd>
  <?php if ($c['note']): ?><dt class="col-sm-3">ملاحظة</dt><dd class="col-sm-9"><?= e($c['note']) ?></dd><?php endif; ?><?php if ($c['status'] !== 'pending'): ?><dt class="col-sm-3">القرار</dt><dd class="col-sm-9"><?= e($c['decided_name'] ?? '') ?> <?= e(substr((string)$c['decided_at'], 0, 16)) ?><?= $c['decision_note'] ? ' — ' . e($c['decision_note']) : '' ?></dd><?php endif; ?></dl></div>
 <?php if ($c['receipt_file_id']): ?><a href="<?= url('files/' . (int)$c['receipt_file_id']) ?>" target="_blank"><?= qimg((int)$c['receipt_file_id'], 'q-img', 'إيصال التحويل') ?></a><?php endif; ?></div>
 <?php if ($c['status'] === 'pending' && can('fees.collect')): ?><hr class="my-2"><div class="d-flex gap-2"><button class="btn btn-success btn-sm" data-api="<?= url('api/v1/school/fees/claims/' . (int)$c['id'] . '/approve') ?>" data-confirm="التأكد من وصول المبلغ؟ سيُقيَّد ويصدر سند قبض.">اعتماد وقيد الدفعة</button><button class="btn btn-outline-danger btn-sm" data-api="<?= url('api/v1/school/fees/claims/' . (int)$c['id'] . '/reject') ?>" data-prompt="سبب الرفض (يُرسل لولي الأمر)" data-prompt-field="note">رفض</button></div><?php endif; ?></div><?php endforeach; ?>
